ALTER TABLE "turnstile"."invitation_delivery" ADD CONSTRAINT "invitation_delivery_attempt_state" CHECK (("turnstile"."invitation_delivery"."state"<>'queued' OR "turnstile"."invitation_delivery"."attempts"<5) AND ("turnstile"."invitation_delivery"."state" NOT IN ('sending','smtp_accepted','unknown') OR "turnstile"."invitation_delivery"."attempts">0));--> statement-breakpoint
ALTER TABLE "turnstile"."invitation_generation" ADD CONSTRAINT "invitation_generation_digests" CHECK ("turnstile"."invitation_generation"."credential_hash" ~ '^[0-9a-f]{64}$' AND "turnstile"."invitation_generation"."recovery_epoch" ~ '^[0-9a-f]{64}$');--> statement-breakpoint
ALTER TABLE "turnstile"."invitation_generation" ADD CONSTRAINT "invitation_generation_lifetime" CHECK ("turnstile"."invitation_generation"."expires_at">"turnstile"."invitation_generation"."created_at" AND "turnstile"."invitation_generation"."expires_at"<="turnstile"."invitation_generation"."created_at"+interval '604800 seconds');